        void AddOption(FlowLayoutPanel panel,CheckBox box,string text,bool enabled,string help){box.Text=text;box.Checked=enabled;box.AutoSize=true;box.Margin=new Padding(3,5,3,8);panel.Controls.Add(box);tips.SetToolTip(box,help);}
