        public void SetRom(string source){romPath.Text=source;RefreshAudioMaps();}
        public void Smoke(string source,string input,string output,bool graphics=false,string section=null){romPath.Text=source;wadPath.Text=input;LoadWad();tabs.SelectedIndex=graphics?2:0;if(graphics)graphicsRefresh();PrepareSmokeSection(section);var timer=new Timer{Interval=500};timer.Tick+=delegate{timer.Stop();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(output);}timer.Dispose();Close();};timer.Start();}
        void AddPath(TableLayoutPanel panel,int row,string label,TextBox field,string filter,bool isWad){panel.Controls.Add(new Label{Text=label,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Theme.Muted},0,row);field.Dock=DockStyle.Fill;field.BackColor=Theme.Raised;field.ForeColor=Theme.Text;panel.Controls.Add(field,1,row);var browse=Theme.Button("Browse...");browse.Dock=DockStyle.Fill;browse.Click+=delegate{using(var dialog=new OpenFileDialog{Filter=filter})if(dialog.ShowDialog(this)==DialogResult.OK){field.Text=dialog.FileName;if(isWad)LoadWad();else if(wad==null)RefreshAudioMaps();}};panel.Controls.Add(browse,2,row);if(isWad)field.Leave+=delegate{if(File.Exists(field.Text)&&(wad==null||!string.Equals(wad.PathName,Path.GetFullPath(field.Text),StringComparison.OrdinalIgnoreCase)))LoadWad();};}
        void LoadWad(){if(string.IsNullOrWhiteSpace(wadPath.Text)){wad=null;levels.Items.Clear();RefreshAudioMaps();return;}try{wad=new WadFile(wadPath.Text);levels.Items.Clear();foreach(string level in wad.Levels)levels.Items.Add(level,wad.Levels.Count<=22||levels.Items.Count==0);RefreshAudioMaps();report.Text="Found "+wad.Levels.Count+" levels. Choose up to 22, then analyze or build.\r\nHover an option for details.";}catch(Exception ex){wad=null;levels.Items.Clear();report.Text=ex.Message;}}
        ConversionOptions Options(){return new ConversionOptions{MergeSectors=merge.Checked,WeldVertices=weld.Checked,CollapseWalls=collapse.Checked,CompactTags=tags.Checked,BestFit=bestFit.Checked,ClosestActions=closest.Checked,RejectDisconnected=reject.Checked,RemoveDecorations=decorations.Checked,LightingStep=new[]{0,8,16,32,64}[lighting.SelectedIndex],MonsterLimit=new[]{0,16,32,48,64,80}[monsters.SelectedIndex]};}
        async void Run(bool analysis){try{FlushText();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Text edits");return;}if(string.IsNullOrWhiteSpace(wadPath.Text)){await RunRetail(analysis);return;}try{Bin.Require(File.Exists(romPath.Text),"Choose your base SNES ROM.");if(wad==null||!string.Equals(wad.PathName,Path.GetFullPath(wadPath.Text),StringComparison.OrdinalIgnoreCase))LoadWad();Bin.Require(wad!=null,"Choose a valid PWAD.");string[] selected=levels.CheckedItems.Cast<string>().ToArray();Bin.Require(selected.Length>0&&selected.Length<=22,"Select 1..22 levels.");string output=null;if(!analysis)using(var dialog=new SaveFileDialog{Filter="SNES ROM and native campaign|*.sfc",FileName="DoomSNESconv-custom.sfc"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;output=Path.GetFullPath(dialog.FileName);}string source=Path.GetFullPath(romPath.Text);WadFile input=wad;ConversionOptions options=Options();bool substitute=lossy.Checked;Enabled=false;ShowReport();report.Text="Analyzing and rebuilding native BSP, collision and platform tables...";try{StorageSummary storageBudget=null;string result=await Task.Run(delegate{return analysis?ConverterProgram.Analyze(source,input,selected,options,substitute,resources,graphicChanges,b=>storageBudget=b,audioChanges,textChanges):ConverterProgram.Convert(source,input,output,selected,options,substitute,resources,graphicChanges,b=>storageBudget=b,audioChanges,textChanges);});report.Text=result;storageMeter.Summary=storageBudget;storageMeter.Invalidate();if(!analysis){campaign=Path.ChangeExtension(output,".dse");play.Enabled=true;}}finally{Enabled=true;}}catch(Exception ex){storageMeter.Summary=new StorageSummary{Error="See conversion report for the allocation failure."};storageMeter.Invalidate();report.Text="Conversion stopped: "+ex.Message+"\r\n\r\nTry the optimization options, fewer maps, or simplify the source PWAD.";ShowReport();}}
        void Play(){try{Bin.Require(!string.IsNullOrEmpty(campaign),"Build or open a campaign first.");string patch=Path.ChangeExtension(campaign,".dse");Bin.Require(File.Exists(patch),"The native .dse campaign sidecar is missing. Rebuild the PWAD with this converter.");Bin.Require(File.Exists(romPath.Text),"Choose the base SNES ROM first.");Bin.Require(!RomLayout.SourceBuilt(new Rom(romPath.Text,resources).Bytes),"This DoomFX source-linked ROM exports for emulators/hardware; the relocated engine cannot run in the native recompiler.");string exe=GameIntegration.Recomp;Bin.Require(exe!=null,"DoomSNESRecomp was not found beside the tools or in the sibling DoomSNESRecomp/build folder.");Process.Start(new ProcessStartInfo{FileName=exe,Arguments=(new Rom(romPath.Text,resources).IsModified?"--modified-rom ":"")+"--rom "+Quote(Path.GetFullPath(romPath.Text))+" --campaign "+Quote(Path.GetFullPath(patch)),WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false});}catch(Exception ex){MessageBox.Show(this,ex.Message,"DoomSNESconv",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
