    public static class ConverterProgram {
        static AudioProject SelectedAudio(AudioProject audio,string[] maps){return audio==null?new AudioProject():new AudioProject{Music=audio.Music.Where(m=>MusicTargets.IsSpecial(m.Map)||maps.Contains(m.Map)).ToList(),Sounds=audio.Sounds.ToList()};}
        public static string Analyze(string source,WadFile wad,string[] levels,ConversionOptions options,bool lossy,string resources,System.Collections.Generic.List<GraphicReplacement> graphics=null,Action<StorageSummary> budget=null,AudioProject audio=null,System.Collections.Generic.List<TextReplacement> texts=null){var rom=new Rom(source,resources);rom.Project.Texts=texts??new System.Collections.Generic.List<TextReplacement>();rom.Project.Graphics=graphics??new System.Collections.Generic.List<GraphicReplacement>();rom.Project.Audio=SelectedAudio(audio,levels);var converter=new WadConverter(rom,resources){AllowLossy=lossy,Options=options};try{converter.Convert(wad,levels,options.MergeSectors);}catch(Exception ex){throw new InvalidDataException(string.Join("\r\n",converter.Report.ToArray())+"\r\n"+ex.Message,ex);}if(budget!=null)budget(rom.Budget);return "ANALYSIS PASSED - no ROM, project or campaign patch written\r\n"+string.Join("\r\n",converter.Report.ToArray())+AudioCli.Report(rom);}
        public static string Convert(string source,WadFile wad,string output,string[] levels,bool merge,bool lossy,string resources){return Convert(source,wad,output,levels,new ConversionOptions{MergeSectors=merge},lossy,resources);}
        public static string Convert(string source,WadFile wad,string output,string[] levels,ConversionOptions options,bool lossy,string resources,System.Collections.Generic.List<GraphicReplacement> graphics=null,Action<StorageSummary> budget=null,AudioProject audio=null,System.Collections.Generic.List<TextReplacement> texts=null){
            string[] outputs={output,Path.ChangeExtension(output,".sned"),Path.ChangeExtension(output,".dse"),Path.ChangeExtension(output,".conversion.txt")};foreach(string path in outputs){Bin.Require(!string.Equals(Path.GetFullPath(source),Path.GetFullPath(path),StringComparison.OrdinalIgnoreCase),"The base ROM cannot be overwritten.");Bin.Require(!string.Equals(wad.PathName,Path.GetFullPath(path),StringComparison.OrdinalIgnoreCase),"The WAD cannot be overwritten.");}Bin.Require(string.Equals(Path.GetExtension(output),".sfc",StringComparison.OrdinalIgnoreCase),"Choose an .sfc output filename.");
            var rom=new Rom(source,resources);rom.Project.Texts=texts??new System.Collections.Generic.List<TextReplacement>();rom.Project.Graphics=graphics??new System.Collections.Generic.List<GraphicReplacement>();rom.Project.Audio=SelectedAudio(audio,levels);var converter=new WadConverter(rom,resources){AllowLossy=lossy,Options=options};byte[] image;try{image=converter.Convert(wad,levels,options.MergeSectors);}catch(Exception ex){throw new InvalidDataException(string.Join("\r\n",converter.Report.ToArray())+"\r\n"+ex.Message,ex);}if(budget!=null)budget(rom.Budget);string project=outputs[1],patch=outputs[2],report=outputs[3];string text="DoomSNESconv conversion completed\r\n"+string.Join("\r\n",converter.Report.ToArray())+"\r\nCampaign: "+string.Join(" -> ",levels)+" -> episode 3 ending\r\nROM (optional emulator): "+output+"\r\nNative recomp campaign: "+patch+"\r\nEditor project: "+project+"\r\nClick Play in DoomSNESRecomp, or run:\r\nDoomSNESRecomp.exe "+(rom.IsModified?"--modified-rom ":"")+"--rom \""+Path.GetFullPath(source)+"\" --campaign \""+Path.GetFullPath(patch)+"\"\r\n";text+=AudioCli.Report(rom);rom.SaveProject(project);rom.SavePatch(patch,image,true);Bin.Atomic(report,System.Text.Encoding.UTF8.GetBytes(text));Bin.Atomic(output,image);return text;
        }
        [STAThread]public static int Main(string[] args){try{if(args.Length>=3&&(args[0]=="--mod-rom"||args[0]=="--analyze-rom")){bool inspect=args[0]=="--analyze-rom";string data=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");var audio=AudioCli.Parse(args,args[1],data);string text=RetailExport.Build(args[1],inspect?null:args[2],data,null,audio,null);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DoomSNESconv-last-run.txt"),text);return 0;}if(args.Length==3&&args[0]=="--recommend"){string data=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");var recommendation=ConversionRecommendations.Analyze(new Rom(args[1],data),new WadFile(args[2]),data,null);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DoomSNESconv-last-run.txt"),recommendation.Report);return 0;}
            if(args.Length>0&&(args[0]=="--convert"||args[0]=="--analyze")){bool analyze=args[0]=="--analyze";int start=analyze?3:4;Bin.Require(args.Length>=start,"Usage: --convert base.sfc input.wad output.sfc [level names] [options], or --analyze base.sfc input.wad [options]");var wad=new WadFile(args[2]);string[] names=args.Skip(start).Where(a=>!a.StartsWith("--")).ToArray();if(args.Contains("--first"))names=wad.Levels.Take(1).ToArray();if(names.Length==0)names=wad.Levels.ToArray();var options=new ConversionOptions{MergeSectors=args.Contains("--merge"),WeldVertices=!args.Contains("--no-weld"),CollapseWalls=!args.Contains("--no-collapse"),CompactTags=!args.Contains("--no-compact-tags"),BestFit=!args.Contains("--no-best-fit"),ClosestActions=!args.Contains("--strict-actions"),RejectDisconnected=!args.Contains("--no-reject"),RemoveDecorations=args.Contains("--remove-scenery")};foreach(string arg in args){if(arg.StartsWith("--lighting="))options.LightingStep=int.Parse(arg.Substring(11));if(arg.StartsWith("--monsters="))options.MonsterLimit=int.Parse(arg.Substring(11));}string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");AudioProject audio=AudioCli.Parse(args,args[1],resources);string text=analyze?Analyze(args[1],wad,names,options,args.Contains("--allow-substitutions"),resources,null,null,audio):Convert(Path.GetFullPath(args[1]),wad,Path.GetFullPath(args[3]),names,options,args.Contains("--allow-substitutions"),resources,null,null,audio);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DoomSNESconv-last-run.txt"),text);return 0;
            }
            Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var form=new ConverterForm();if(args.Length==2&&args[0]=="--rom")form.SetRom(args[1]);if((args.Length==4||args.Length==5)&&(args[0]=="--ui-smoke-test"||args[0]=="--ui-graphics-smoke-test"))form.Shown+=delegate{form.Smoke(args[1],args[2],args[3],args[0]=="--ui-graphics-smoke-test",args.Length==5?args[4]:null);};Application.Run(form);return 0;
        }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DoomSNESconv-error.log"),ex.ToString());if(args.Length==0)MessageBox.Show(ex.Message,"DoomSNESconv");return 1;}}
    }
